<?php use App\Services\CredentialService as C; ?>
<div class="row g-3"><div class="col-lg-4"><form class="card-s" method="post" action="<?= url('api/v1/school/credentials') ?>" data-ajax data-reload novalidate><?= csrf_field() ?><h2 class="h6">إصدار شهادة</h2>
 <div class="mb-2"><label class="form-label" for="sn">رقم الطالب</label><input class="form-control" id="sn" name="student_no" dir="ltr" required></div>
 <div class="mb-2"><label class="form-label" for="k">النوع</label><select class="form-select" id="k" name="kind"><?php foreach (C::KINDS as $k => $l): ?><option value="<?= $k ?>"><?= e($l) ?></option><?php endforeach; ?></select></div>
 <div class="mb-2"><label class="form-label" for="t">عنوان الشهادة</label><input class="form-control" id="t" name="title" required></div><div class="mb-2"><label class="form-label" for="nt">ملاحظات</label><input class="form-control" id="nt" name="notes"></div>
 <button class="btn btn-primary w-100">إصدار</button><p class="small text-muted mt-2">رابط التحقق العام: <a href="<?= url('verify') ?>" target="_blank">/verify</a></p></form></div>
<div class="col-lg-8"><div class="card-s"><?php if (!$rows): ?><div class="empty-state">لا شهادات.</div><?php endif; ?>
<?php foreach ($rows as $c): ?><div class="border-bottom py-2 d-flex justify-content-between flex-wrap gap-2"><div><?= e($c['title']) ?> — <?= e($c['full_name']) ?> <?= $c['revoked_at'] ? '<span class="badge text-bg-danger">مسحوبة</span>' : '' ?><div class="small text-muted"><span dir="ltr"><?= e($c['verify_code']) ?></span> · <?= e($c['issued_on']) ?></div></div>
 <div class="d-flex gap-1"><a class="btn btn-sm btn-outline-secondary" target="_blank" href="<?= url('school/credentials/' . (int)$c['id'] . '/print') ?>">طباعة</a><?php if (!$c['revoked_at']): ?><button class="btn btn-sm btn-outline-danger" data-api="<?= url('api/v1/school/credentials/' . (int)$c['id'] . '/revoke') ?>" data-prompt="سبب السحب" data-prompt-field="reason">سحب</button><?php endif; ?></div></div><?php endforeach; ?></div></div></div>
